{"path": "tax.py", "content": "from decimal import Decimal, ROUND_HALF_UP

CENT = Decimal("0.01")


def to_decimal(value):
    # Go through str so binary float noise (e.g. 0.1) doesn't leak into rounding.
    return value if isinstance(value, Decimal) else Decimal(str(value))


def line_tax(price, rate):
    """Tax for one line, rounded half-up to whole cents (0.125 -> 0.13)."""
    return (to_decimal(price) * to_decimal(rate)).quantize(CENT, rounding=ROUND_HALF_UP)
"}

{"path": "cart.py", "content": "from tax import CENT, line_tax, to_decimal


def total_with_tax(prices, rate):
    # Each line's tax is already rounded to cents; sum exactly, then return a float.
    total = sum((to_decimal(p) + line_tax(p, rate) for p in prices), to_decimal(0))
    return float(total.quantize(CENT))
"}

